insert into refs select 'competing-decision',public.command_v2_workflow('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000003','decisions.create',pg_temp.ctx(pg_temp.id('competing-request')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','planId',value->>'planId','selectedOfferIds',jsonb_build_array(value->>'offerId'),'consideredOfferIds',jsonb_build_array(value->>'offerId'),'policyId',null,'rationale','Competing request before capacity commitment','evidence',jsonb_build_array(pg_temp.ev())))->'record' from refs where name='competing-offer';
insert into refs select 'competing-booking',public.command_v2_workflow('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000003','bookings.create',pg_temp.ctx(pg_temp.id('competing-request')),gen_random_uuid(),jsonb_build_object('schemaVersion','2.0','decisionId',pg_temp.id('competing-decision'),'offerId',value->>'offerId','authorization','AUTHORIZE','evidence',pg_temp.ev()))->'record' from refs where name='competing-offer';
insert into refs values('prepare-key',jsonb_build_object('id',gen_random_uuid()));
create function pg_temp.prepare(expected integer default 1,k uuid default pg_temp.id('prepare-key')) returns jsonb language sql as $$select public.prepare_v2_delegated_booking('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000003',pg_temp.id('booking'),expected,k,'PREPARE_AUTHORIZED_CAPACITY');$$;
select throws_ok($$select pg_temp.prepare(99)$$,'PT409','STALE_DRAFT','stale booking cannot commit resources');
reset role;
-- Failure after preparing the first hold must roll back all compound side effects.
create function pg_temp.reject_second_hold() returns trigger language plpgsql as $$begin if new.capacity_calendar_id=pg_temp.id('calendar-2') then raise exception 'TEST_SECOND_HOLD_CONFLICT' using errcode='PT409';end if;return new;end;$$;
create trigger dispatch_atomic_test before insert on public.capacity_reservations for each row execute function pg_temp.reject_second_hold();
set local role authenticated;
select throws_ok($$select pg_temp.prepare()$$,'PT409','TEST_SECOND_HOLD_CONFLICT','a failure on the second truck aborts the compound command');
reset role;
select is((select count(*)::integer from public.capacity_reservations where booking_id=pg_temp.id('booking')),0,'first hold rolled back after second hold failure');
select is((select count(*)::integer from public.transport_executions where booking_id=pg_temp.id('booking')),0,'planned execution also rolled back');
select is((select status from public.v2_bookings where id=pg_temp.id('booking')),'AUTHORIZED','no premature booking confirmation');
drop trigger dispatch_atomic_test on public.capacity_reservations;
update private.v2_catalog_grants set revoked_at=now() where auth_user_id='c2310000-0000-4000-8000-000000000001' and revoked_at is null;
set local role authenticated;
select is(pg_temp.prepare(),null::jsonb,'revoked Carrier authority falls back to manual confirmation');
reset role;
select is((select count(*)::integer from public.capacity_reservations where booking_id=pg_temp.id('booking')),0,'revocation leaves no capacity writes');
update private.v2_catalog_grants set revoked_at=null where auth_user_id='c2310000-0000-4000-8000-000000000001';
set local role authenticated;
insert into refs values('scheduled',pg_temp.prepare());
select is((select value#>>'{data,status}' from refs where name='scheduled'),'SCHEDULED','Carrier delegation confirms booking atomically after Client consent');
select is(pg_temp.prepare(),(select value from refs where name='scheduled'),'network retry replays even after booking version changes');
select throws_ok($$select pg_temp.prepare(2)$$,'PT409','IDEMPOTENCY_CONFLICT','same key with different booking version is a conflict');
select throws_ok($$select public.prepare_v2_delegated_booking('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000003',pg_temp.id('competing-booking'),1,gen_random_uuid(),'PREPARE_AUTHORIZED_CAPACITY')$$,'PT409','PLAN_OR_OFFER_NOT_CURRENT','second accepted offer cannot displace the first confirmed operation');
reset role;
select is((select count(*)::integer from public.capacity_reservations where booking_id=pg_temp.id('competing-booking')),0,'conflicting request creates no partial reservations');
select is((select count(*)::integer from public.capacity_reservations where booking_id=pg_temp.id('booking') and status='CONFIRMED'),2,'both trucks committed together');
select is((select count(*)::integer from public.transport_executions where booking_id=pg_temp.id('booking') and status='PLANNED'),1,'operation remains scheduled and has not departed');
select is((select count(*)::integer from private.dispatch_booking_audit where booking_id=pg_temp.id('booking')),1,'Carrier policy and customer actors audited');
select ok(not has_function_privilege('anon','public.prepare_v2_delegated_booking(uuid,uuid,uuid,integer,uuid,text)','EXECUTE'),'anonymous cannot prepare or confirm bookings');
select * from finish();rollback;
